	for _, w := range []int64{0, -1, math.MinInt64} {
		if err := RunAggregate(strings.NewReader(""), w, &bytes.Buffer{}, &bytes.Buffer{}); err == nil {
			t.Fatalf("expected error for window %d", w)
		}
	}
