		{"watermark regression", `{"type":"watermark","time":10}` + "\n" + `{"type":"watermark","time":9}` + "\n", 2, "backwards"},
		{
			"window end overflow",
			`{"type":"event","key":"k","time":9223372036854775807,"value":1}` + "\n",
