	stdout2, _, err := runPartitioned(t, good, 1000, 2)
	if err != nil {
		t.Fatalf("unexpected error for resume at 2000: %v", err)
	}
	if stdout2 != want {
		t.Fatalf("stdout mismatch after resume:\n got: %q\nwant: %q", stdout2, want)
	}
}

